def dbg(g):
    h,w=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row)
    rare={c for c,n in cnt.items() if n<15}
    struct=[c for c,_ in cnt.most_common() if c not in rare][:2]
    print('counts',cnt.most_common(),'rare',rare,'struct',struct)
    def purity(color):
        best=0
        for r in range(h): best=max(best,sum(g[r][c]==color for c in range(w))/w)
        for c in range(w): best=max(best,sum(g[r][c]==color for r in range(h))/h)
        return best
    print({c:purity(c) for c in struct})
